'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function readState(){try{return JSON.parse(localStorage.getItem('mad-weekend-v1'))||{}}catch{return {}}}
const stored=readState();
const madridDate=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Madrid',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
let state={day:['2026-10-24','2026-10-25'].indexOf(madridDate)+1,view:['plan','map','ideas','home'].includes(location.hash.slice(1))?location.hash.slice(1):'plan',surprise:stored.surprise!==false,revealed:Array.isArray(stored.revealed)?stored.revealed:[],done:Array.isArray(stored.done)?stored.done:[],ideas:!!stored.ideas,mapIdeas:false,ideaFilter:'day'};
let map=null,toastTimer=null,activePlace=null;
function save(){try{localStorage.setItem('mad-weekend-v1',JSON.stringify({surprise:state.surprise,revealed:state.revealed,done:state.done,ideas:state.ideas}))}catch{}}
function unlocked(stop,now=Date.now()){return !state.surprise||state.revealed.includes(stop.id)||now>=Date.parse(stop.at)}
function timeLabel(at){return new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Madrid',weekday:'short',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(at));}
function mapUrl(p,mode='walking',origin=''){const q=new URLSearchParams({api:'1',destination:(p.mapQuery||p.address.split(' ·')[0])+', Madrid',travelmode:mode});if(origin)q.set('origin',origin);return 'https://www.google.com/maps/dir/?'+q;}
function external(url,label,cls=''){return `<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`}
function visibleStops(){return DAYS[state.day].stops.filter(s=>unlocked(s));}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function syncControls(){document.querySelectorAll('[data-view]').forEach(b=>{const selected=b.dataset.view===state.view;b.classList.toggle('active',selected);b.setAttribute('aria-current',selected?'page':'false')});$('#spoilerToggle').setAttribute('aria-checked',String(state.surprise));$('#spoilerToggle b').textContent=state.surprise?'ON':'OFF';$('#daySelector').classList.toggle('hidden',state.view==='home');$('#daySelector').innerHTML=DAYS.map((d,i)=>`<button class="day-btn ${i===state.day?'active':''}" data-day="${i}" aria-pressed="${i===state.day}"><strong>${d.date}</strong><span>${d.label}<small>OCTOBER</small></span></button>`).join('')}
function heading(title,sub,index=''){return `<div class="section-heading"><div><h2>${title}</h2><p>${sub}</p></div>${index?`<span class="day-index">${index}</span>`:''}</div>`}
function mapMarkup(large=false){return `<div class="map-box"><div class="map-head">Your corner of Madrid <span>Tap a pin to explore</span></div><div id="map" class="map ${large?'large':''}" aria-label="Map of revealed stops and starting stations"></div><div class="map-caption"><p>Green: revealed stops · rust: home stations${state.mapIdeas?' · gold: optional ideas':''}</p><p>Home pins mark metro stations, not doorways. Map positions are approximate.</p></div></div>`}
function stopMarkup(s,i){const p=PLACES[s.place],open=unlocked(s),done=state.done.includes(s.id);return `<article class="stop ${!open?'locked':''} ${done?'done':''}" id="stop-${s.id}"><div class="stop-time">${s.time.replace('–','<br>– ')}</div><div class="stop-body"><div class="stop-top"><span class="tag">${open?esc(p.kind):'A little surprise'}</span><span class="stop-number">${String(i+1).padStart(2,'0')}</span></div><h3>${esc(open?p.name:s.hint)}</h3><p>${esc(s.desc)}</p><div class="stop-actions">${open?`<button class="text-btn" data-place="${s.place}">Story & details</button>${external(mapUrl(p),'Directions','text-btn')}<button class="check-btn" data-done="${s.id}" aria-label="${done?'Unmark':'Mark'} ${esc(p.name)} as visited" aria-pressed="${done}">${done?'✓':'○'}</button>`:`<button class="text-btn" data-reveal="${s.id}">Peek now</button>`}</div>${!open?`<small class="reveal-time">Reveals ${timeLabel(s.at)} · Madrid time</small>`:''}</div></article>`}
function renderPlan(){const d=DAYS[state.day],done=d.stops.filter(s=>state.done.includes(s.id)).length;return `${heading(d.theme,d.subtitle,String(state.day+1).padStart(2,'0'))}<div class="layout"><div class="timeline">${d.stops.map(stopMarkup).join('')}</div><aside class="sidebar">${mapMarkup()}<div class="note"><p class="eyebrow">THE RHYTHM OF THE DAY</p><h3>${d.pace}</h3><p>${d.note}</p><div class="budget"><span>Food budget / person</span><strong>${d.budget}</strong></div><p class="small">Planning estimates, not confirmed menu prices.</p><div class="progress-row"><span>Your little travel log</span><span>${done} / ${d.stops.length} stops</span></div><div class="progress-track"><span style="width:${done/d.stops.length*100}%"></span></div></div><div class="note"><h3>Leave room for a detour.</h3><p>${state.day===0?'Pick one pre-dinner activity. If the airport runs late, go straight to dinner.':state.day===1?'Lunch and conversation can run over. Trim the river or move the museum to 16:30.':'A slow coffee is a complete afternoon plan. Choose one extra, not three.'}</p><button class="text-btn" data-view="ideas">Browse nearby alternatives</button></div><div class="note"><h3>${state.surprise?'Some things are better discovered.':'The whole weekend, unlocked.'}</h3><p>${state.surprise?'Future stop names and pins stay hidden until their reveal time. Peek at any one, or switch off Surprise mode to plan everything.':'Surprise mode can hide future stops again. Stories still wait behind their own reveal buttons.'}</p></div></aside></div>`}
function renderMap(){const items=visibleStops();return `${heading('Follow your curiosity.','The selected day’s revealed stops, plus both starting stations.')}<div class="filter-row"><button class="chip ${state.mapIdeas?'active':''}" id="mapIdeas" aria-pressed="${state.mapIdeas}">${state.mapIdeas?'✓ ':''}Show optional ideas on map</button><button class="chip" id="fitMap">Fit all pins</button></div>${state.surprise?'<div class="notice"><span>✧</span><p>Future stops are hidden. Reveal them in the plan, or turn Surprise mode off. Adding optional ideas is a deliberate peek.</p></div>':''}${mapMarkup(true)}<div class="map-list">${items.map((s,i)=>`<button data-place="${s.place}"><small>${i+1}</small>${esc(PLACES[s.place].name)}</button>`).join('')}</div>${!items.length?'<p class="small">Only the two home stations are visible so far. Your stops will appear as they unlock.</p>':''}`}
function renderIdeas(){if(state.surprise&&!state.ideas)return `${heading('Keep a little wiggle room.','Alternatives, not extra obligations.')}<div class="empty"><p class="eyebrow">SPOILER CHECK</p><h3>These ideas give a little away.</h3><p>Browse museum swaps, nearby walks and other dinner options whenever you feel like it. Opening this list does not change the main plan.</p><button class="btn" id="revealIdeas">Show me the alternatives</button></div>`;const items=IDEAS.filter(i=>state.ideaFilter==='all'||i.day===DAYS[state.day].id);return `${heading('Keep a little wiggle room.','A menu of alternatives. Choose a swap, not a longer to-do list.')}<div class="filter-row"><button class="chip ${state.ideaFilter==='day'?'active':''}" data-idea-filter="day">Near this day’s plan</button><button class="chip ${state.ideaFilter==='all'?'active':''}" data-idea-filter="all">All weekend</button></div><div class="idea-grid">${items.map(i=>{const p=PLACES[i.place];return `<article class="idea-card"><span class="tag">${i.tag} · ${i.day}</span><h3>${esc(p.name)}</h3><p>${i.why}</p><div class="idea-meta"><span>${i.minutes}</span><span>${i.cost}</span></div><button class="text-btn" data-place="${i.place}">Explore this idea</button></article>`}).join('')}</div>`}
function renderHome(){return `${heading('Two bases. One weekend.','Save the station names. Your hosts will handle the final doorway.')}<div class="home-grid">${['fer','jose'].map(k=>{const p=PLACES[k];return `<article class="home-card"><p class="eyebrow">${p.area.toUpperCase()}</p><h3>${p.name}</h3><span class="line ${k==='fer'?'l1':'l5'}">${k==='fer'?'1':'5'}</span>${k==='fer'?'<span class="line l6">6</span>':''}<p><strong>${k==='fer'?'Calle de Cavanilles':'Calle de Ezequiel Solana'}</strong><br>${k==='fer'?'Pacífico metro':'Quintana metro'}</p><p>${p.practical}</p>${external(mapUrl(p,'transit'),`Get to ${p.area}`,'btn')} <button class="text-btn" data-place="${k}">Details</button></article>`}).join('')}</div><div class="notice"><span>↗</span><p><strong>Line 6 works · 24–25 October</strong>The CRTM alert lists the western Cuatro Caminos–Lucero section as closed. Avoid planning a full loop on L6. L1 is the simplest centre connection from Pacífico. ${external(SOURCES.metro,'Current official alerts')}</p></div><div class="home-grid"><div class="note"><h3>From Barajas to Fer’s</h3><p>Allow roughly 90–120 minutes from landing to bags dropped, depending on the terminal and luggage. Open a live transit route once you know your terminal; do not assume every airport journey starts in T4.</p>${external('https://www.google.com/maps/dir/?api=1&origin=Adolfo+Suarez+Madrid+Barajas+Airport&destination=Pacifico+Metro+Madrid&travelmode=transit','Airport → Pacífico','text-btn')}</div><div class="note"><h3>A useful phrase or two</h3><p>“Cuatro cañas, por favor” — four small beers, please.<br>“¿Podemos pedir para compartir?” — can we order to share?<br>“Sin carne ni pescado” — no meat or fish.<br>“La cuenta, por favor” — the bill, please.</p></div></div><div class="note"><h3>Monday is travel day.</h3><p>Fer and José are working. Check your own flight, terminal and route on Sunday evening, and leave a comfortable airport margin.</p></div>`}
function mapEntries(){const entries=[...visibleStops().map((s,i)=>({id:s.place,label:String(i+1),type:PLACES[s.place].kind==='home'?'home':''})),...['fer','jose'].map((k,i)=>({id:k,label:i?'J':'F',type:'home'}))];if(state.view==='map'&&state.mapIdeas)IDEAS.filter(i=>i.day===DAYS[state.day].id).forEach(i=>entries.push({id:i.place,label:'+',type:'idea'}));return entries.filter((e,i,a)=>a.findIndex(x=>x.id===e.id)===i)}
function overviewMap(el){
 const entries=mapEntries(),xs=entries.map(e=>PLACES[e.id].lng),ys=entries.map(e=>PLACES[e.id].lat);
 const minX=Math.min(...xs)-.009,maxX=Math.max(...xs)+.009,minY=Math.min(...ys)-.006,maxY=Math.max(...ys)+.006;
 const xy=p=>[(p.lng-minX)/(maxX-minX)*600,420-(p.lat-minY)/(maxY-minY)*420];
 el.innerHTML=`<svg class="overview-map" viewBox="0 0 600 420" role="group" aria-label="Overview of revealed places. Use directions for street-level navigation."><defs><pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M 40 0 L 0 0 0 40" fill="none" stroke="#cbd5c8" stroke-width="1"/></pattern></defs><rect width="600" height="420" fill="#e5eadf"/><rect width="600" height="420" fill="url(#grid)"/><text x="25" y="32" fill="#64716a" font-size="13" font-family="Arial">MADRID · LOCATION OVERVIEW</text><text x="559" y="32" fill="#173c36" font-size="14">N ↑</text>${entries.map(e=>{const p=PLACES[e.id],[x,y]=xy(p);return `<g role="button" tabindex="0" data-map-place="${e.id}" aria-label="${esc(p.name)}" class="overview-pin"><title>${esc(p.name)}</title><circle cx="${x}" cy="${y}" r="17" fill="${e.type==='home'?'#ba492d':e.type==='idea'?'#7e6d45':'#173c36'}" stroke="white" stroke-width="3"/><text x="${x}" y="${y+4}" text-anchor="middle" fill="white" font-family="Arial" font-size="12" font-weight="bold">${e.label}</text></g>`}).join('')}<text x="25" y="400" fill="#64716a" font-size="11" font-family="Arial">Relative locations · not a street map</text></svg>`;
 el.querySelectorAll('[data-map-place]').forEach(pin=>{pin.addEventListener('click',()=>openPlace(pin.dataset.mapPlace));pin.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openPlace(pin.dataset.mapPlace)}})});
 $('.map-caption')?.insertAdjacentHTML('beforeend','<p>Overview shown because this browser cannot display the full map. Tap a pin or use Directions for street routes.</p>');
 const fit=$('#fitMap');if(fit){fit.disabled=true;fit.textContent='Overview fitted'}
}
function mountMap(){
 const el=$('#map');if(!el)return;
 const fallback=()=>overviewMap(el);
 if(!window.maplibregl){console.warn('Guide map: library unavailable');fallback();return}
 try{map=new maplibregl.Map({container:el,style:'https://tiles.openfreemap.org/styles/liberty',center:[-3.7,40.419],zoom:12,attributionControl:false,scrollZoom:false});}catch(error){console.warn('Guide map:',error.message);fallback();return}
 map.addControl(new maplibregl.NavigationControl({showCompass:false}),'top-left');
 map.addControl(new maplibregl.AttributionControl({compact:false}),'bottom-right');
 let errorShown=false;map.on('error',()=>{if(!errorShown){errorShown=true;$('.map-caption')?.insertAdjacentHTML('beforeend','<p>Some map data could not load. The place list and directions remain available.</p>')}});
 const entries=[...visibleStops().map((s,i)=>({id:s.place,label:String(i+1),type:PLACES[s.place].kind==='home'?'home':''})),...['fer','jose'].map((k,i)=>({id:k,label:i?'J':'F',type:'home'}))];
 if(state.view==='map'&&state.mapIdeas)IDEAS.filter(i=>i.day===DAYS[state.day].id).forEach(i=>entries.push({id:i.place,label:'+',type:'idea'}));
 const seen=new Set(),bounds=new maplibregl.LngLatBounds();
 for(const e of entries){if(seen.has(e.id))continue;seen.add(e.id);const p=PLACES[e.id],pos=[p.lng,p.lat];bounds.extend(pos);const pin=document.createElement('button');pin.className='map-pin '+e.type;pin.textContent=e.label;pin.setAttribute('aria-label',p.name);pin.title=p.name;pin.addEventListener('click',()=>openPlace(e.id));new maplibregl.Marker({element:pin}).setLngLat(pos).addTo(map)}
 if(!bounds.isEmpty())map.fitBounds(bounds,{padding:40,maxZoom:14,duration:0});map._guideBounds=bounds;
}
function render(){if(map){map.remove();map=null}syncControls();$('#pageContent').innerHTML=state.view==='plan'?renderPlan():state.view==='map'?renderMap():state.view==='ideas'?renderIdeas():renderHome();mountMap()}
function showDialog(html){$('#dialogContent').innerHTML=html;if(!$('#detailDialog').open)$('#detailDialog').showModal()}
function openPlace(id){const p=PLACES[id];if(!p)return;activePlace=id;showDialog(`<p class="dialog-kicker">${esc(p.area)} · ${p.kind}</p><h2 id="dialogTitle">${esc(p.name)}</h2><p class="address">${esc(p.address)}</p><p>${esc(p.story)}</p>${p.secret?`<details><summary>A little story to discover</summary><p>${esc(p.secret)}</p></details>`:''}<p class="practical">${esc(p.practical)}</p><div class="dialog-links">${external(p.wiki,p.wikiLabel||'Read on Wikipedia','btn secondary')}${p.source?external(p.source,'Official info / source','btn secondary'):''}${p.tickets?external(p.tickets,'Tickets','btn secondary'):''}${p.phone?`<a class="btn secondary" href="tel:${p.phone}">Call the venue</a>`:''}</div><div class="route-options"><label for="routeOrigin">Directions from</label><select id="routeOrigin"><option value="current">My location</option><option value="fer">Fer · Pacífico station</option><option value="jose">José · Quintana station</option></select><a class="btn" id="routeLink" href="${esc(mapUrl(p))}" target="_blank" rel="noopener noreferrer">Open route ↗</a></div><p class="small">Google Maps handles the live route. Home starting points are metro stations. Prices, crowds and travel times can change.</p>`)}
function openSources(){showDialog(`<p class="dialog-kicker">The useful small print</p><h2 id="dialogTitle">Ready for the weekend.</h2><p>Last checked: <strong>23 October 2026</strong>. This is a curated plan, not a live feed. Follow the source links for current opening times, tickets and service changes.</p><p>Food estimates for the weekend: roughly <strong>€75–115 per person</strong>, before transport and extra drinks. No tables or tickets have been booked.</p><p>Surprise mode hides future stop names and pins until the displayed Madrid time. You can peek early. These are playful spoilers, not password-protected secrets. Your reveal and visited choices are saved on this browser only.</p><p>The clocks go back on Sunday 25 October: 03:00 becomes 02:00. The guide uses <strong>Europe/Madrid</strong>, including that change.</p><div class="source-list">${[['MAN admission',SOURCES.man],['MAN opening hours',SOURCES.manHours],['Prado hours & free slots',SOURCES.prado],['Reina Sofía visitor information',SOURCES.reina],['Sunday event · municipal route notice',SOURCES.trash],['Rastro hours',SOURCES.rastro],['Metro service alerts',SOURCES.metro],['Casa Paco listing',SOURCES.paco],['Sala Equis listing',SOURCES.equis],['Pez Tortilla locations',SOURCES.pez]].map(([n,u])=>external(u,n)).join('')}</div><p class="small">Historic landmarks link to their Wikipedia articles. Bars without a dedicated article link to their neighbourhood, explicitly labelled. Maps by OpenFreeMap, © OpenMapTiles and OpenStreetMap contributors. Rendered with MapLibre GL JS.</p><button class="text-btn" id="resetProgress">Reset visited stops and early reveals</button>`)}
function showTravel(){showDialog(`<p class="dialog-kicker">Checked 23 October</p><h2 id="dialogTitle">Mind the metro works.</h2><p>For <strong>24–25 October</strong>, the current CRTM alert lists the <strong>western L6 section between Cuatro Caminos and Lucero</strong> as closed. Pacífico’s L1 is the easier option for the centre.</p><p>A separate L10 closure is listed between <strong>Cuzco and Nuevos Ministerios</strong>. The suggested Saturday journey from Príncipe Pío to Alonso Martínez does not cross that section.</p><p>José’s base: <strong>Quintana, L5</strong>. Fer’s base: <strong>Pacífico, L1 and L6</strong>. Check the live service before each journey.</p>${external(SOURCES.metro,'Open current CRTM alerts','btn')}`)}
function changeView(v){state.view=v;history.replaceState(null,'','#'+v);render();$(v==='home'?'#pageContent':'#daySelector').scrollIntoView({block:'start',behavior:'auto'})}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){changeView(b.dataset.view);return}if(b.dataset.day){state.day=Number(b.dataset.day);render();return}if(b.dataset.place){openPlace(b.dataset.place);return}if(b.dataset.reveal){state.revealed.push(b.dataset.reveal);save();render();toast('One more piece of Madrid, revealed.');return}if(b.dataset.done){state.done=state.done.includes(b.dataset.done)?state.done.filter(x=>x!==b.dataset.done):[...state.done,b.dataset.done];save();render();return}if(b.dataset.ideaFilter){state.ideaFilter=b.dataset.ideaFilter;render();return}if(b.id==='spoilerToggle'){state.surprise=!state.surprise;save();render();toast(state.surprise?'Future stops are hidden again.':'The full plan is now visible.');return}if(b.id==='revealIdeas'){state.ideas=true;save();render();return}if(b.id==='mapIdeas'){state.mapIdeas=!state.mapIdeas;render();return}if(b.id==='fitMap'&&map&&map._guideBounds&&!map._guideBounds.isEmpty()){map.fitBounds(map._guideBounds,{padding:40,maxZoom:14,duration:0});return}if(b.id==='infoButton'){openSources();return}if(b.id==='travelNotice'){showTravel();return}if(b.classList.contains('close-dialog')){$('#detailDialog').close();return}if(b.id==='resetProgress'){state.done=[];state.revealed=[];state.ideas=false;state.mapIdeas=false;save();$('#detailDialog').close();render();toast('Your local travel log has been reset.')}});
document.addEventListener('change',e=>{if(e.target.id==='routeOrigin'){const key=e.target.value,p=PLACES[activePlace];$('#routeLink').href=key==='current'?mapUrl(p):mapUrl(p,'transit',key==='fer'?'Pacífico metro Madrid':'Quintana metro Madrid')}});
$('#detailDialog').addEventListener('click',e=>{if(e.target===$('#detailDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(['plan','map','ideas','home'].includes(v)){state.view=v;render()}});
function tick(){const t=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Madrid',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date());$('#madridClock').textContent=t+' in Madrid';const signature=visibleStops().map(s=>s.id).join();if(tick.last!==undefined&&signature!==tick.last&&state.surprise&&!$('#detailDialog').open)render();tick.last=signature}
render();tick();setInterval(tick,30000);
